lemma sound (defines : H.DefinesPLoNFrameClass 𝔽) (d : H ⊢! φ) : 𝔽 ⊧ φ := by
  intro F hF;
  have := defines.mpr hF;
  exact Semantics.RealizeSet.setOf_iff.mp this φ d;

