  intro h;
  obtain ⟨⟨_, F⟩, hF⟩ := nonempty;
  simpa using sound defines h hF;

lemma consistent_of_defines (defines : H.DefinesPLoNFrameClass 𝔽) (nonempty : 𝔽.Nonempty) : System.Consistent H := by
  exact?

